#!/usr/bin/env python3
"""Calcula a área do retângulo descrito em medidas.txt."""

from pathlib import Path

MEDIDAS = Path(__file__).parent / "medidas.txt"


def ler_medidas(caminho):
    valores = {}
    for linha in caminho.read_text().splitlines():
        linha = linha.strip()
        if not linha:
            continue
        chave, _, valor = linha.partition("=")
        valores[chave.strip()] = float(valor.strip())
    return valores


def main():
    m = ler_medidas(MEDIDAS)
    largura = m["largura"]
    altura = m["altura"]
    area = largura * altura
    print(f"largura = {largura:g}")
    print(f"altura  = {altura:g}")
    print(f"área    = {area:g}")


if __name__ == "__main__":
    main()

